### Final Full‐Example (you can copy‑paste)

```js
// app.js
const express          = require('express');
const helmet           = require('helmet');
const cors             = require('cors');
const rateLimit        = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// ----------- Core Middlewares -------------
app.use(helmet());
app.use(cors());               // ← configure origins if needed
app.use(express.json());

// Rate limiting (100 req/min per IP)
const limiter = rateLimit({
  windowMs: 1 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// ----------- Routes ----------------------
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

app.get('/users',
  query('sort')
    .optional()
    .isIn(['name', 'id'])
    .withMessage('sort must be name or id'),

  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com' }
    ];

    const out = req.query.sort
      ? users.sort((a,b)=>a[req.query.sort].localeCompare(b[req.query.sort]))
      : users;

    res.json(out);
  }
);

// 404 catcher
app.all('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    method: req.method,
    path: req.originalUrl
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] ${err.stack ?? err.message}`);
  res.status(err.statusCode || 500).json({
    error: err.message || 'Internal Server Error'
  });
});

// ----------- Server start -----------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

---

### Quick Takeaways

1. **Never expose stack traces** or internal details to clients.  
2. **Validate** all incoming data, even query strings.  
3. **Auth‑shield** with HTTP headers, CORS, and rate‑limiting.  
4. **Central error handling** keeps the app stable and logs everything consistently.

