      // add scriptSrc, styleSrc, imgSrc etc. as needed
    },
  })
);
```

> *Benefits:* HTTP‑only headers like `X‑Content-Type‑Options`, `X‑Download-Options`, `X‑Frame-Options`, `X‑XSS-Protection`, `Strict-Transport-Security`, etc.

