// app.js
/**
 * A secure and production‑ready Express skeleton.
 *
 * Features:
 * - Helmet – security headers
 * - CORS – configurable whitelist
 * - Rate limiting – IP based limiting
 * - Async wrapper – catches rejected promises
 * - Structured error handling
 * - Environment‑aware configuration (dotenv)
 * - Basic request validation (example added for /users?id=)
 */
require('dotenv').config();          // Load .env file

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

/* --------------------------- Middleware -------------------------------- */

app.use(helmet());       // ✔️ Security headers

// Adjust the CORS Whitelist in the environment (comma‑separated list)
const corsWhitelist = (process.env.CORS_WHITELIST || '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

app.use(
  cors({
    origin: (origin, callback) => {
      // Allow requests with no origin (e.g. mobile or curl)
      if (!origin || corsWhitelist.includes(origin)) return callback(null, true);
      return callback(new Error('Not allowed by CORS'));
    },
  })
);

// Rate limit – 100 requests / 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

/* --------------------------- Helpers --------------------------------- */

/**
 * A tiny async wrapper that forwards any rejected promise to next().
 * Works with Express 5 style async/await handlers.
 */
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

/* --------------------------- Routes ---------------------------------- */

app.get(
  '/health',
  asyncHandler(async (_req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  })
);

/**
 * Example: localhost:3000/users?id=1
 *  * id → optional numeric query param, validated by express‑validator
 */
app.get(
  '/users',
  // Validation chain
  query('id').optional().isInt({ min: 1 }).toInt(),
  asyncHandler(async (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Return a 400 with a concise error message
      return res.status(400).json({ errors: errors.array() });
    }

    // Simulated data layer; replace with real DB calls
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by id if supplied
    const result = req.query.id
      ? users.filter((u) => u.id === req.query.id)
      : users;

    res.json(result);
  })
);

/* --------------------------- Error Handling --------------------------- */

// Generic error logger (In prod you would pipe this to a file/monitoring service)
app.use((err, _req, res, _next) => {
  // Capture non‑critical internal errors
  if (process.env.NODE_ENV !== 'production') {
    console.error(err); // Still log stack traces in dev
  } else {
    // In production avoid logging PII – use a proper logger
    console.error(err.message);
  }

  // Provide a safe JSON error response
  const status = err.status || 500;
  const payload = {
    status,
    error: err.message || 'Internal Server Error',
  };
  // If not production, expose stack? (only useful for debugging)
  if (process.env.NODE_ENV !== 'production') payload.stack = err.stack;
  res.status(status).json(payload);
});

/* --------------------------- Server Start ----------------------------- */

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

