});

app.get('/search', async (req, res, next) => {
  const { error, value } = searchSchema.validate(req.query);
  if (error) return res.status(400).json({ error: error.details[0].message });
  try {
    const results = await db.search(value.q, value.limit);
    res.json(results);
  } catch (err) {
    next(err);
  }
});
```

