/* app.js – a secure, well‑structured Express starter */

"use strict";

const express = require("express");
const helmet = require("helmet");
const cors = require("cors");
const rateLimit = require("express-rate-limit");
const morgan = require("morgan");
// uncomment if you need async error handling
// require("express-async-errors");
const app = express();

/* ---------- Config ---------- */
const PORT = parseInt(process.env.PORT ?? "3000", 10);
const NODE_ENV = process.env.NODE_ENV ?? "development";

/* ---------- Security Middlewares ---------- */
app.use(helmet()); // secure HTTP headers
app.use(cors({ origin: NODE_ENV === "production" ? [/* your origins */] : "*" })); // adjust whitelist
app.use(express.json({ limit: "1mb" })); // JSON body limiting
app.use(express.urlencoded({ extended: true, limit: "1mb" })); // form data limiting

/* ---------- Logging ---------- */
app.use(
  morgan(
    NODE_ENV === "production"
      ? "combined" // more verbose for prod
      : "dev" // concise for dev
  )
);

/* ---------- Rate Limiting ---------- */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 200, // limit each IP to 200 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

/* ---------- Routes ---------- */

app.get(
  "/health",
  (req, res) => {
    res.json({ status: "ok", timestamp: new Date().toISOString() });
  },
  /* you could add query validation here if needed */
);

app.get(
  "/users",
  (req, res) => {
    // In real world, you’d fetch from a DB & run *deep* validation/sanitisation
    return res.json([
      { id: 1, name: "Alice", email: "alice@example.com" },
      { id: 2, name: "Bob", email: "bob@example.com" },
    ]);
  }
);

/* ---------- 404 Handler ---------- */
app.use((req, res) => {
  res.status(404).json({ error: "Not Found" });
});

/* ---------- Global Error Handler ---------- */
app.use((err, req, res, next) => {
  /* eslint-disable no-console */
  console.error(err); // log full stack in dev
  /* eslint-enable no-console */

  const status = err.status || err.statusCode || 500;
  res.status(status).json({
    error: status === 500 ? "Internal Server Error" : err.message,
  });
});

/* ---------- Server ---------- */
app.once("listening", () => {
  console.log(`Server running on port ${PORT}`);
});
app.listen(PORT, () => console.log(`Listening on ${PORT}`));

module.exports = app;
```

