// app.js
// ----------------------------
// 1️⃣  Imports
// ----------------------------
const express = require('express');
const helmet = require('helmet');          // Security headers
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');          // HTTP request logger
const app = express();

// ----------------------------
// 2️⃣  Global Middlewares (in order)
// ----------------------------

// Trust proxy headers if behind a reverse proxy (e.g., nginx)
app.set('trust proxy', true);

// Helmet – set a sane set of security headers
app.use(helmet());

// CORS – only allow requests from known origins
// (Adjust the `origin` value to match your front‑end)
app.use(
  cors({
    origin: ['https://example.com', 'http://localhost:3000'], // whitelist
    optionsSuccessStatus: 200,
  })
);

// Rate limiting – automatically returns 429 on throttled requests
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,   // 15 minutes
  max: 100,                    // limit each IP to 100 requests per window
  standardHeaders: true,       // Return `RateLimit-*` headers
  legacyHeaders: false,        // Don’t send `X-RateLimit-*`
});
app.use(limiter);

// Log HTTP requests (in Common format, can switch to JSON)
app.use(morgan('combined'));

// ----------------------------
// 3️⃣  Body parser guard
// ----------------------------
app.use(express.json({ limit: '10kb' })); // guard against large payloads

// ----------------------------
// 4️⃣  Routes (kept identical for now)
// ----------------------------
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ----------------------------
// 5️⃣  404 handler
// ----------------------------
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    requestedPath: req.originalUrl,
  });
});

// ----------------------------
// 6️⃣  Global error handler
// ----------------------------
app.use((err, req, res, next) => {
  // Log the raw error for debugging
  console.error(err);
  // Don't leak stack trace or internal details to clients
  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
  });
});

// ----------------------------
// 7️⃣  Start server – PORT from env
// ----------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What changed & why it matters

| Section | Improvement | Impact |
|---------|-------------|--------|
| **Helmet** | Adds `X‑Content‑Type‑Options`, `Strict-Transport-Security`, `X‑Frame‑Options`, `X‑XSS‑Protection`, `Referrer-Policy`, etc. | Mitigates XSS, click‑jacking, MIME sniffing. |
| **CORS** | Explicit whitelist. | Prevents unwanted cross‑origin requests. |
| **Rate limiter** | Rate‑limits all endpoints. | Protects against brute‑force and DoS. |
| **Trust proxy** | Useful if behind nginx or a load balancer. | Correct IP logs, HSTS enforcement. |
| **Morgan** | Structured logging to console (or to a file). | Easier debugging and audit trails. |
| **Body‑parser guard** | Small JSON limit and default body parsing. | Avoids large payload attacks. |
| **404 handler** | Consistent JSON 404. | Client clarity, no HTML left‑behind. |
| **Error handler** | Centralized, removes stack traces from HTTP responses. | Avoid accidental info leakage. |
| **PORT env** | Configurable service front‑gate. | Workable in Docker, CI, stage/prod. |

