## 3. Minimal patch to `app.js`

Below is a **drop‑in replacement** that incorporates the fixes described above. Feel free to cherry‑pick the parts you want.

```js
// app.js – secured & hardened
// =================================

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
// Use dotenv in production to read env vars
require('dotenv').config();

const app = express();

// --------------------------------------------------
// 1️⃣  Basic middleware
// --------------------------------------------------
app.use(helmet());                            // security headers
app.use(cors({ origin: 'https://trusted.example.com', credentials: true })); // restrict CORS
app.use(express.json());                      // parse JSON bodies

// --------------------------------------------------
// 2️⃣  Rate limiting
// --------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,    // 15 minutes
  max: 200,                    // max 200 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// --------------------------------------------------
// 3️⃣  Routes (static for now – keep them simple)
// --------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ]);
});

// --------------------------------------------------
// 4️⃣  Global error handler
// --------------------------------------------------
app.use((err, req, res, next) => {
  console.error('❌ Unhandled error', err);
  res.status(err.status || 500).json({ error: 'Internal Server Error' });
});

// --------------------------------------------------
// 5️⃣  Graceful shutdown
// --------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

const gracefulShutdown = () => {
  console.log('\n🛑 Shutting down gracefully...');
  server.close(() => {
    console.log('✅ Closed out remaining connections');
    process.exit(0);
  });
};
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// (Optional) capture unhandled rejections – causes exit or log
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection at:', reason);
  // Here you could exit or just log
});

module.exports = app;
```

**Key take‑aways**

* **Helmet** – injects numerous good‑for‑security HTTP headers.  
* **CORS** – pin your API to a known origin.  
* **Rate limiting** – mitigate brute‑force and DoS.  
* **Global error handler** – no stack traces leak, server doesn’t crash.  
* **Graceful shutdown** – ensures connections close cleanly.  
* **Environment‑based port** – easier deployments.  

---

## 4. Next steps

1. **Add validation** – for any future POST/PUT routes use `express-validator` or `joi`.  
2. **Auth** – wrap protected routes with JWT or OAuth2 checks.  
3. **Data sanitisation** – escape output when rendering HTML (avoid XSS).  
4. **HTTPS** – ensure the service runs behind a TLS terminator (NGINX, Cloud Front, etc.) or just let the framework serve HTTPS directly if you’re running standalone.  

Those changes will make the application considerably safer and more production‑ready. Happy coding!

